-- Tables of the ricorsa-console store the portfolio adapter reads (DDL as in production), with fixture rows.
CREATE TABLE IF NOT EXISTS `customers` ( `id` text PRIMARY KEY NOT NULL, `kind` text DEFAULT 'company' NOT NULL, `name` text NOT NULL, `company` text, `email` text, `phone` text, `website` text, `address` text, `status` text DEFAULT 'lead' NOT NULL, `plan` text DEFAULT 'free' NOT NULL, `mrr_cents` integer DEFAULT 0 NOT NULL, `currency` text DEFAULT 'USD' NOT NULL, `source` text, `owner_id` text, `tags` text DEFAULT '[]' NOT NULL, `notes` text DEFAULT '' NOT NULL, `ricorsa_user_id` text, `custom` text DEFAULT '{}' NOT NULL, `last_contact_at` integer, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `updated_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `billing_cycle` text);
CREATE TABLE IF NOT EXISTS `communications` ( `id` text PRIMARY KEY NOT NULL, `customer_id` text NOT NULL, `contact_id` text, `kind` text DEFAULT 'note' NOT NULL, `direction` text DEFAULT 'out' NOT NULL, `subject` text DEFAULT '' NOT NULL, `body` text DEFAULT '' NOT NULL, `to_email` text, `status` text DEFAULT 'logged' NOT NULL, `provider` text, `provider_id` text, `error` text, `invoice_id` text, `by_staff_id` text, `at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL );
CREATE TABLE IF NOT EXISTS `licenses` ( `id` text PRIMARY KEY NOT NULL, `customer_id` text NOT NULL, `key` text NOT NULL, `product` text DEFAULT 'ricorsa' NOT NULL, `plan` text DEFAULT 'pro' NOT NULL, `seats` integer DEFAULT 1 NOT NULL, `status` text DEFAULT 'active' NOT NULL, `starts_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `ends_at` integer, `auto_renew` integer DEFAULT false NOT NULL, `notes` text DEFAULT '' NOT NULL, `created_by` text, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `updated_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `billing_cycle` text );
CREATE TABLE IF NOT EXISTS `trials` ( `id` text PRIMARY KEY NOT NULL, `customer_id` text NOT NULL, `plan` text DEFAULT 'pro' NOT NULL, `status` text DEFAULT 'active' NOT NULL, `started_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `ends_at` integer NOT NULL, `converted_at` integer, `notes` text DEFAULT '' NOT NULL, `created_by` text, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `updated_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL );
CREATE TABLE IF NOT EXISTS `invoices` ( `id` text PRIMARY KEY NOT NULL, `number` text NOT NULL, `customer_id` text NOT NULL, `status` text DEFAULT 'draft' NOT NULL, `currency` text DEFAULT 'USD' NOT NULL, `items` text DEFAULT '[]' NOT NULL, `subtotal_cents` integer DEFAULT 0 NOT NULL, `tax_cents` integer DEFAULT 0 NOT NULL, `total_cents` integer DEFAULT 0 NOT NULL, `paid_cents` integer DEFAULT 0 NOT NULL, `issued_at` integer, `due_at` integer, `paid_at` integer, `bill_to` text, `notes` text DEFAULT '' NOT NULL, `terms` text DEFAULT '' NOT NULL, `paypal_invoice_id` text, `paypal_status` text, `paypal_link` text, `sent_to` text, `sent_at` integer, `created_by` text, `created_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL, `updated_at` integer DEFAULT (strftime('%s','now') * 1000) NOT NULL );
